using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EnduringScrappingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/EnduringScrappingCustomDescription", order = 0)]
public class EnduringScrappingCustomDescription : CompanionScrappingCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string arg = (battleAction as CompanionScrappingAction).BattleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).LowercaseFirst().RemoveLast();
		string arg2 = Smart.Format(base.localizationManager.GetLocalizedForEach(), arg, GetRawLocalizedDescription(battleAction));
		return GetBreakASentinelLocalizedString() + "\n" + Smart.Format(GetIfYouDoLocalizedString(), arg2).AddDotIfJapaneseOrKoreanOrTraditionalChinese() + "\n" + base.localizationManager.GetLocalizedString("NextTimeSentinelRepairedRestorePreviousEffects");
	}
}
